W=$HOME/work/loop; grep MATCH $W/human.log | tail -n +17 | cut -c1-200; grep "failed\|stage\|net [hbs]A" $W/human.log | tail -3 | cut -c1-160; grep "rows of" $W/human.log | tail -3 | cut -c1-230; for t in hA bA sAh; do grep -o "\"epoch\": [0-9], \"seconds\": [0-9]*" $W/exp-human/$t.log 2>/dev/null | tail -1; done; tail -n 1 $W/runs.log | cut -c1-150; echo "xh-hs-p $(wc -l < $W/runs/xh-hs-p/results.jsonl)"; date -u +%T
